node --test tests/visible.test.mjs && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createClient } from './src/client.mjs';

const calls = [];
const delays = [];
let keyCount = 0;
let attempt = 0;
const request = createClient({
  transport: async call => {
    calls.push(call);
    attempt++;
    if (attempt === 1) return { status: 500, headers: { 'Retry-After': '2' } };
    if (attempt === 2) return { status: 503 };
    return { status: 200 };
  },
  sleep: async ms => delays.push(ms),
  keyFactory: () => `key-${++keyCount}`,
  maxAttempts: 3,
  baseMs: 150,
});
assert.equal((await request({ method: 'POST', url: '/x', headers: { trace: 'yes' } })).status, 200);
assert.deepEqual(delays, [2000, 300]);
assert.deepEqual(calls.map(call => call.headers['idempotency-key']), ['key-1', 'key-1', 'key-1']);
assert.ok(calls.every(call => call.headers.trace === 'yes'));
assert.equal(keyCount, 1);

let explicitKeyFactoryCalls = 0;
let explicitAttempts = 0;
const explicit = createClient({
  transport: async call => {
    explicitAttempts++;
    assert.equal(call.headers['Idempotency-Key'], 'provided');
    return { status: explicitAttempts === 1 ? 429 : 200 };
  },
  sleep: async () => {},
  keyFactory: () => { explicitKeyFactoryCalls++; return 'generated'; },
});
assert.equal((await explicit({ method: 'POST', url: '/x', headers: { 'Idempotency-Key': 'provided' } })).status, 200);
assert.equal(explicitKeyFactoryCalls, 0);
assert.equal(explicitAttempts, 2);
EOF

