patches.after:
function getHeader(headers, name) {
  if (headers == null) return undefined;
  if (typeof headers.get === 'function') return headers.get(name) ?? undefined;

  const key = Object.keys(headers).find(headerName => headerName.toLowerCase() === name);
  return key === undefined ? undefined : headers[key];
}

export function delayFor(response, attempt, baseMs) {
  const retryAfter = getHeader(response?.headers, 'retry-after');
  const value = typeof retryAfter === 'string' ? retryAfter.trim() : retryAfter;
  const isNumericValue = typeof value === 'number' || typeof value === 'string';
  if (isNumericValue && value !== '' && Number.isFinite(Number(value)) && Number(value) >= 0) {
    return Number(value) * 1000;
  }
  return baseMs * 2 ** (attempt - 1);
}

export function shouldRetry(response) {
  const status = response?.status;
  return status === 429 || (status >= 500 && status <= 599);
}
